package com.ascend.app;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;
public class ScheduleReceiver extends BroadcastReceiver{
 @Override public void onReceive(Context c,Intent in){PendingResult pr=goAsync();String title=in.getStringExtra("title");if(title==null)title="Scheduled task";String end=in.getStringExtra("end");show(c,title,end);reschedule(c,in);String text="Yo! It's "+title+" time. Lock in."+(end==null?"":" Your session ends at "+end+".");new android.speech.tts.TextToSpeech(c.getApplicationContext(),st->{if(st==android.speech.tts.TextToSpeech.SUCCESS){android.speech.tts.TextToSpeech t=(android.speech.tts.TextToSpeech)c.getApplicationContext();t.setLanguage(Locale.US);t.setSpeechRate(1.02f);t.speak(text,android.speech.tts.TextToSpeech.QUEUE_FLUSH,null,"ASCEND_"+System.currentTimeMillis());}pr.finish();});}
 private void show(Context c,String title,String end){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"ascend_schedule"):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("ASCEND • LOCK IN").setContentText("It's time for "+title+(end==null?"":" • until "+end)).setPriority(Notification.PRIORITY_MAX).setCategory(Notification.CATEGORY_ALARM).setAutoCancel(true).setVibrate(new long[]{0,300,150,500});((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify((int)System.currentTimeMillis(),b.build());}
 private void reschedule(Context c,Intent in){String r=in.getStringExtra("repeat");if(r==null||r.equals("Once"))return;AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);Calendar x=Calendar.getInstance();x.set(Calendar.SECOND,0);x.set(Calendar.MILLISECOND,0);x.add(Calendar.DAY_OF_MONTH,1);int s=in.getIntExtra("start",0);x.set(Calendar.HOUR_OF_DAY,s/60);x.set(Calendar.MINUTE,s%60);while(!match(x,r))x.add(Calendar.DAY_OF_MONTH,1);if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())return;Intent n=new Intent(c,ScheduleReceiver.class);n.putExtras(in);PendingIntent p=PendingIntent.getBroadcast(c,in.getIntExtra("id",0),n,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(Build.VERSION.SDK_INT>=23)am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,x.getTimeInMillis(),p);else am.setExact(AlarmManager.RTC_WAKEUP,x.getTimeInMillis(),p);}
 private boolean match(Calendar x,String r){int d=x.get(Calendar.DAY_OF_WEEK);return r.equals("Every day")||(r.equals("Weekdays")&&d>=2&&d<=6)||(r.equals("Weekend")&&(d==1||d==7));}
}
